    Bug 1998575 - try to fix intermittent comm/calendar/test/browser/preferences/browser_alarmDefaultValue.js. r=vineet


    I suspect the timeout in showTab via selectPrefPane cause the scroll from there to happen at the wrong time.
    The failure screenshot suggest it didn't scroll to the element we wanted, or if it did, did the other scroll
    after, so what we want to click is out of the viewport already.

    Differential Revision: https://phabricator.services.mozilla.com/D273085

diff --git a/calendar/test/browser/preferences/head.js b/calendar/test/browser/preferences/head.js
index 0c1ee41b0dc..15f2ff5f56a 100644
--- a/calendar/test/browser/preferences/head.js
+++ b/calendar/test/browser/preferences/head.js
@@ -45,6 +45,8 @@ async function openNewPrefsTab(paneID, scrollPaneTo, otherArgs) {
     }
     Assert.greater(container.scrollTop, 0, "Prefs page did scroll when it was supposed to");
   }
+  await new Promise(resolve => prefsWindow.setTimeout(resolve));
+  info(`Opened new prefs tab; paneID=${paneID}, scrollPaneTo=${scrollPaneTo}`);
   return { prefsDocument, prefsWindow };
 }
